   "    </ul>\n    <button class=\"primary\" style=\"width:100%;\" onclick=\"cerrarModal(); cargarEmpresas();\">Listo</button>\n  `;\n}\n\n// ---- Personalización de términos (por empresa) ----\n",
   "    </ul>\n    <button class=\"primary\" style=\"width:100%;\" onclick=\"cerrarModal(); cargarEmpresas();\">Listo</button>\n  `;\n}\n\n// ==================== 🛠️ Soporte técnico (Peymar) ====================\n// Solo el área de soporte (permiso \"Soporte\"). Reporte → orden de servicio\n// (el cliente la firma desde un link por WhatsApp o aquí mismo) → diagnóstico\n// (sin costos: refacciones y evidencia) + apartado interno → resolución al\n// cliente con encuesta → enviado → cerrado. Los documentos llevan el logo de\n// la empresa.\n\nlet SOP = { lista: null, filtro: 'abiertos', q: '', actual: null, catalogos: null };\nconst SOP_ESTADOS = {\n  orden_pendiente_firma: ['✍️ Falta firma', '#E6A014'], diagnostico: ['🔎 En diagnóstico', '#5B9BD5'],\n  resolucion_enviada: ['📤 Resolución enviada', '#8E6BD1'], enviado: ['🚚 Enviado', '#2E9E6B'],\n  cerrado: ['✅ Cerrado', '#555'], cancelado: ['🚫 Cancelado', '#D8192F'],\n};\nconst SOP_PASOS = ['orden_pendiente_firma', 'diagnostico', 'resolucion_enviada', 'enviado', 'cerrado'];\nconst sopChip = (e) => { const [t, c] = SOP_ESTADOS[e] || [e, '#888']; return `<span style=\"display:inline-block; font-size:11px; font-weight:800; color:#fff; background:${c}; border-radius:12px; padding:2px 9px; white-space:nowrap;\">${t}</span>`; };\nconst sopTipo = (t) => t === 'garantia' ? '<span style=\"font-size:11px; font-weight:800; color:#0E4C92;\">🛡️ GARANTÍA</span>' : '<span style=\"font-size:11px; font-weight:800; color:#2E7D4F;\">🛠️ MANTENIMIENTO</span>';\nconst sopLiga = (r) => `${window.location.origin}/soporte/${r.token}`;\n\nfunction _ocultarPantallasParaSoporte() {\n  ['app', 'menuScreen', 'equiposScreen', 'proyectosScreen', 'marketingScreen', 'reparacionesScreen', 'laboratorioScreen',\n   'entregasScreen', 'checadorPrecioScreen', 'dashboardScreen', 'superadminScreen', 'comprasScreen', 'rhScreen',\n   'crmScreen', 'shopifyScreen', 'turnosScreen'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; });\n}\n\nasync function abrirSoporte() {\n  _ocultarPantallasParaSoporte();\n  document.getElementById('soporteScreen').style.display = 'block';\n  document.getElementById('whoamiSoporte').innerHTML = `<b>${escapeHtml(SESION.usuario.nombre)}</b><br>${NOMBRES_ROL[SESION.usuario.rol] || SESION.usuario.rol}`;\n  await cargarSoporte();\n}\n\nfunction volverATableroDesdeSoporte() {\n  document.getElementById('soporteScreen').style.display = 'none';\n  document.getElementById('menuScreen').style.display = 'block';\n}\n\nasync function cargarSoporte() {\n  const cont = document.getElementById('soporteContenido');\n  cont.innerHTML = '<p style=\"color:var(--muted);\">Cargando…</p>';\n  try {\n    const r = await api(`/api/soporte?estado=${encodeURIComponent(SOP.filtro === 'todos' ? '' : SOP.filtro)}&q=${encodeURIComponent(SOP.q)}`);\n    SOP.lista = r.reportes;\n    SOP.catalogos = r;\n  } catch (e) { cont.innerHTML = `<p class=\"error-msg\">${escapeHtml(e.message)}</p>`; return; }\n  pintarSoporte();\n}\n\nfunction pintarSoporte() {\n  const cont = document.getElementById('soporteContenido');\n  const filtros = [['abiertos', 'Abiertos'], ...Object.keys(SOP_ESTADOS).map(k => [k, SOP_ESTADOS[k][0]]), ['todos', 'Todos']];\n  cont.innerHTML = `\n    <div style=\"display:flex; gap:6px; flex-wrap:wrap; margin-bottom:10px;\">\n      ${filtros.map(([k, t]) => `<button class=\"${SOP.filtro === k ? 'primary' : 'secondary'}\" style=\"padding:5px 10px; font-size:12px;\" onclick=\"SOP.filtro='${k}'; cargarSoporte();\">${t}</button>`).join('')}\n    </div>\n    <div style=\"display:flex; gap:8px; margin-bottom:12px;\">\n      <input id=\"sopBuscar\" placeholder=\"Buscar cliente, No. de serie, teléfono, folio…\" value=\"${escapeHtml(SOP.q)}\" style=\"flex:1;\"\n        onkeydown=\"if(event.key==='Enter'){ SOP.q=this.value.trim(); cargarSoporte(); }\" />\n      <button class=\"secondary\" onclick=\"SOP.q=document.getElementById('sopBuscar').value.trim(); cargarSoporte();\">Buscar</button>\n    </div>\n    <div style=\"overflow-x:auto;\">\n    <table class=\"users\">\n      <thead><tr><th>Folio</th><th>Servicio</th><th>Cliente</th><th>Unidad dental / Serie</th><th>Estatus</th><th>Fecha</th><th></th></tr></thead>\n      <tbody>\n        ${SOP.lista.map(r => `\n          <tr style=\"cursor:pointer;\" onclick=\"abrirReporteSoporte(${r.id})\">\n            <td><b>${escapeHtml(r.folio_txt)}</b></td>\n            <td>${sopTipo(r.tipo_servicio)}</td>\n            <td>${escapeHtml(r.cliente_nombre)}<div style=\"font-size:11px; color:var(--muted);\">${escapeHtml(r.cliente_telefono || '')}${r.cliente_ciudad ? ' · ' + escapeHtml(r.cliente_ciudad) : ''}</div></td>\n            <td>${escapeHtml(r.tipo_unidad || '—')}${r.modelo ? ' · ' + escapeHtml(r.modelo) : ''}<div style=\"font-size:11px; color:var(--muted);\">Serie: ${escapeHtml(r.numero_serie || '—')}</div></td>\n            <td>${sopChip(r.estado)}${r.encuesta_en ? '<div style=\"font-size:10px; margin-top:2px;\">⭐ encuesta contestada</div>' : ''}</td>\n            <td style=\"white-space:nowrap; font-size:12px;\">${fmtFechaCorta(r.creado_en)}</td>\n            <td style=\"font-size:11px; color:var(--muted);\">${r.evidencias ? `📎 ${r.evidencias}` : ''}</td>\n          </tr>`).join('') || '<tr><td colspan=\"7\" class=\"empty-col\">— no hay reportes con este filtro —</td></tr>'}\n      </tbody>\n    </table>\n    </div>`;\n}\n\n// ---- Nuevo reporte ----\nfunction _datalist(id, valores) {\n  return `<datalist id=\"${id}\">${[...new Set((valores || []).filter(Boolean))].map(v => `<option value=\"${escapeHtml(v)}\">`).join('')}</datalist>`;\n}\n\nfunction abrirNuevoSoporte() {\n  const c = SOP.catalogos || { sugerencias: {} };\n  const sg = c.sugerencias || {};\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button>\n    <h2>🛠️ Nuevo reporte de soporte</h2>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; text-transform:uppercase;\">1. Tipo de servicio *</label>\n    <div style=\"display:flex; gap:10px; margin:6px 0 14px;\">\n      <label class=\"cv-caja\" style=\"flex:1; cursor:pointer; display:flex; gap:8px; align-items:center;\"><input style=\"width:auto;\" type=\"radio\" name=\"sn_tipo\" value=\"mantenimiento\" /> <b>🛠️ Mantenimiento</b></label>\n      <label class=\"cv-caja\" style=\"flex:1; cursor:pointer; display:flex; gap:8px; align-items:center;\"><input style=\"width:auto;\" type=\"radio\" name=\"sn_tipo\" value=\"garantia\" /> <b>🛡️ Garantía</b></label>\n    </div>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; text-transform:uppercase;\">2. Datos del cliente</label>\n    <div class=\"row-2\">\n      <div class=\"field\"><label>Nombre / consultorio *</label><input id=\"sn_nombre\" /></div>\n      <div class=\"field\"><label>WhatsApp / teléfono</label><input id=\"sn_tel\" inputmode=\"tel\" placeholder=\"10 dígitos\" /></div>\n    </div>\n    <div class=\"row-2\">\n      <div class=\"field\"><label>Correo</label><input id=\"sn_email\" type=\"email\" /></div>\n      <div class=\"field\"><label>Ciudad / estado</label><input id=\"sn_ciudad\" list=\"sn_l_ciudad\" />${_datalist('sn_l_ciudad', sg.cliente_ciudad)}</div>\n    </div>\n    <div class=\"field\"><label>Dirección (para el envío)</label><input id=\"sn_dir\" /></div>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; text-transform:uppercase;\">3. Equipo</label>\n    <div class=\"row-2\">\n      <div class=\"field\"><label>Tipo de unidad dental</label><input id=\"sn_unidad\" list=\"sn_l_unidad\" placeholder=\"ej. Unidad dental electromecánica\" />${_datalist('sn_l_unidad', sg.tipo_unidad)}</div>\n      <div class=\"field\"><label>Modelo</label><input id=\"sn_modelo\" list=\"sn_l_modelo\" />${_datalist('sn_l_modelo', sg.modelo)}</div>\n    </div>\n    <div class=\"field\"><label>Número de serie</label><input id=\"sn_serie\" style=\"text-transform:uppercase;\" /></div>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; text-transform:uppercase;\">4. ¿Cuál es el problema? *</label>\n    <div class=\"field\"><textarea id=\"sn_problema\" rows=\"4\" placeholder=\"Lo que reporta el cliente, con el mayor detalle posible\"></textarea></div>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; text-transform:uppercase;\">5. Evidencia (fotos, videos o audios del WhatsApp)</label>\n    <p style=\"font-size:12px; color:var(--muted); margin:4px 0;\">En WhatsApp: mantén presionada la foto o video → Guardar / Compartir → y aquí elígelos. En WhatsApp Web: descárgalos y súbelos.</p>\n    <div class=\"field\"><input type=\"file\" id=\"sn_archivos\" multiple accept=\"image/*,video/*,audio/*,.pdf\" /></div>\n    <div id=\"sn_error\" class=\"error-msg\"></div>\n    <div id=\"sn_progreso\" style=\"font-size:12px;\"></div>\n    <button class=\"primary\" style=\"width:100%; padding:12px;\" onclick=\"crearSoporte(this)\">📄 Crear orden de servicio</button>`;\n  abrirModal();\n}\n\nasync function _comprimirImagen(file, max = 1600) {\n  if (!file.type.startsWith('image/') || file.type === 'image/gif') return file;\n  try {\n    const bmp = await createImageBitmap(file);\n    const k = Math.min(1, max / Math.max(bmp.width, bmp.height));\n    const cv = document.createElement('canvas');\n    cv.width = Math.round(bmp.width * k); cv.height = Math.round(bmp.height * k);\n    cv.getContext('2d').drawImage(bmp, 0, 0, cv.width, cv.height);\n    const blob = await new Promise(ok => cv.toBlob(ok, 'image/jpeg', 0.82));\n    return blob ? new File([blob], (file.name || 'foto').replace(/\\.\\w+$/, '') + '.jpg', { type: 'image/jpeg' }) : file;\n  } catch (e) { return file; }\n}\n\nasync function subirEvidenciasSoporte(id, archivos, etapa, progreso) {\n  let i = 0;\n  for (const original of archivos) {\n    i++;\n    if (progreso) progreso.textContent = `Subiendo evidencia ${i} de ${archivos.length}…`;\n    const f = await _comprimirImagen(original);\n    if (f.size > 20 * 1024 * 1024) { alert(`${original.name} pesa más de 20 MB; no se subió.`); continue; }\n    const fd = new FormData();\n    fd.append('archivo', f, f.name || 'archivo'); fd.append('etapa', etapa); fd.append('descripcion', '');\n    const r = await fetch(`${API}/api/soporte/${id}/evidencias`, { method: 'POST', headers: headers(false), body: fd });\n    if (!r.ok) { const j = await r.json().catch(() => ({})); alert(`${original.name}: ${j.detail || 'no se pudo subir'}`); }\n  }\n  if (progreso) progreso.textContent = '';\n}\n\nasync function crearSoporte(btn) {\n  const v = (id) => document.getElementById(id).value.trim();\n  const tipo = (document.querySelector('input[name=\"sn_tipo\"]:checked') || {}).value;\n  const err = document.getElementById('sn_error'); err.textContent = '';\n  if (!tipo) { err.textContent = 'Elige el tipo de servicio: mantenimiento o garantía.'; return; }\n  if (!v('sn_nombre')) { err.textContent = 'Falta el nombre del cliente.'; return; }\n  if (!v('sn_problema')) { err.textContent = 'Describe el problema.'; return; }\n  const archivos = [...document.getElementById('sn_archivos').files];\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const r = await api('/api/soporte', { method: 'POST', body: JSON.stringify({\n        tipo_servicio: tipo, cliente_nombre: v('sn_nombre'), cliente_telefono: v('sn_tel') || null, cliente_email: v('sn_email') || null,\n        cliente_ciudad: v('sn_ciudad') || null, cliente_direccion: v('sn_dir') || null, tipo_unidad: v('sn_unidad') || null,\n        modelo: v('sn_modelo') || null, numero_serie: v('sn_serie').toUpperCase() || null, problema: v('sn_problema') }) });\n      if (archivos.length) await subirEvidenciasSoporte(r.id, archivos, 'reporte', document.getElementById('sn_progreso'));\n      mostrarExito(`Orden ${r.folio_txt} creada. Ahora mándasela al cliente para que la firme.`);\n      cargarSoporte();\n      await abrirReporteSoporte(r.id);\n    } catch (e) { err.textContent = e.message; }\n  });\n}\n\n// ---- Detalle del reporte ----\nasync function abrirReporteSoporte(id) {\n  try { SOP.actual = await api(`/api/soporte/${id}`); }\n  catch (e) { alert(e.message); return; }\n  if (!SOP.catalogos) { try { SOP.catalogos = await api('/api/soporte?estado=abiertos'); } catch (e) { SOP.catalogos = {}; } }\n  pintarReporteSoporte();\n  abrirModal();\n}\n\nfunction _telWhatsApp(tel) {\n  let d = String(tel || '').replace(/\\D/g, '');\n  if (d.length === 10) d = '52' + d;\n  if (d.length === 12 && d.startsWith('52')) d = '521' + d.slice(2);\n  return d;\n}\n\nfunction _pasosSoporte(estado) {\n  if (estado === 'cancelado') return `<div style=\"margin:8px 0;\">${sopChip('cancelado')}</div>`;\n  const i = SOP_PASOS.indexOf(estado);\n  const nombres = ['Orden / firma', 'Diagnóstico', 'Resolución', 'Enviado', 'Cerrado'];\n  return `<div style=\"display:flex; gap:4px; margin:10px 0; flex-wrap:wrap;\">${nombres.map((n, k) => `\n    <div style=\"flex:1; min-width:90px; text-align:center; font-size:11px; font-weight:700; padding:6px 4px; border-radius:6px;\n      background:${k < i ? 'rgba(46,158,107,0.18)' : k === i ? 'rgba(91,155,213,0.25)' : 'rgba(155,157,159,0.12)'};\n      border:1px solid ${k === i ? '#5B9BD5' : 'transparent'};\">${k < i ? '✔ ' : ''}${n}</div>`).join('')}</div>`;\n}\n\nfunction pintarReporteSoporte() {\n  const r = SOP.actual;\n  const cat = SOP.catalogos || {};\n  const sg = cat.sugerencias || {};\n  const firmado = !!r.firma_en;\n  const cerrado = ['cerrado', 'cancelado'].includes(r.estado);\n  const i = r.interno || {};\n  const evid = (etapa) => r.evidencias.filter(e => e.etapa === etapa);\n  const listaEvid = (etapa) => `\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap; margin:6px 0;\">\n      ${evid(etapa).map(e => `\n        <div style=\"width:110px; border:1px solid var(--line); border-radius:6px; padding:4px; font-size:10px; text-align:center;\">\n          <div class=\"sop-thumb\" data-id=\"${e.id}\" data-tipo=\"${escapeHtml(e.tipo || '')}\" style=\"height:70px; display:flex; align-items:center; justify-content:center; cursor:pointer; background:rgba(155,157,159,0.12); border-radius:4px; overflow:hidden;\" onclick=\"verEvidenciaSoporte(${e.id})\">\n            ${(e.tipo || '').startsWith('image') ? '🖼️' : (e.tipo || '').startsWith('video') ? '🎬' : (e.tipo || '').startsWith('audio') ? '🎙️' : '📄'}</div>\n          <div style=\"overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\" title=\"${escapeHtml(e.nombre || '')}\">${escapeHtml(e.descripcion || e.nombre || '')}</div>\n          ${cerrado ? '' : `<a href=\"#\" style=\"color:#D8192F;\" onclick=\"borrarEvidenciaSoporte(${e.id}); return false;\">quitar</a>`}\n        </div>`).join('') || '<span style=\"font-size:12px; color:var(--muted);\">— sin evidencia —</span>'}\n    </div>\n    ${cerrado ? '' : `<label class=\"secondary\" style=\"display:inline-flex; gap:6px; cursor:pointer; padding:6px 10px; border:1px solid rgba(155,157,159,0.45); border-radius:var(--radius); font-size:12px;\">\n      📎 Agregar fotos / videos<input type=\"file\" multiple accept=\"image/*,video/*,audio/*,.pdf\" style=\"display:none;\" onchange=\"agregarEvidenciaSoporte(this, '${etapa}')\" /></label>`}`;\n  const acciones = [];\n  acciones.push(`<button class=\"secondary\" onclick=\"pdfSoporte('orden')\">📄 Orden de servicio${firmado ? ' (firmada)' : ''}</button>`);\n  if (!firmado && !cerrado) {\n    acciones.push(`<button class=\"primary\" onclick=\"whatsappSoporte('orden')\">📲 Mandar por WhatsApp para firmar</button>`);\n    acciones.push(`<button class=\"secondary\" onclick=\"copiarLigaSoporte()\">🔗 Copiar link</button>`);\n    acciones.push(`<button class=\"secondary\" onclick=\"abrirFirmaPresencialSoporte()\">✍️ Firmar aquí (en persona)</button>`);\n  }\n  if (r.resolucion_enviada_en) acciones.push(`<button class=\"secondary\" onclick=\"pdfSoporte('resolucion')\">📄 Diagnóstico y resolución</button>`);\n  if (r.resolucion_enviada_en && !cerrado) acciones.push(`<button class=\"secondary\" onclick=\"whatsappSoporte('resolucion')\">📲 Reenviar resolución</button>`);\n  if (r.estado === 'resolucion_enviada') acciones.push(`<button class=\"primary\" onclick=\"cambiarEstadoSoporte('enviado')\">🚚 Marcar como enviado</button>`);\n  if (r.estado === 'enviado') acciones.push(`<button class=\"primary\" onclick=\"cambiarEstadoSoporte('cerrado')\">✅ Cerrar reporte</button>`);\n  if (!cerrado) acciones.push(`<button class=\"danger\" onclick=\"cambiarEstadoSoporte('cancelado')\">🚫 Cancelar</button>`);\n  if (cerrado) acciones.push(`<button class=\"secondary\" onclick=\"cambiarEstadoSoporte('${r.resolucion_enviada_en ? 'resolucion_enviada' : (firmado ? 'diagnostico' : 'orden_pendiente_firma')}')\">↺ Reabrir</button>`);\n  const refac = (r.refacciones && r.refacciones.length ? r.refacciones : [{ cantidad: 1, descripcion: '', numero_parte: '' }]);\n  const costos = (i.costos && i.costos.length ? i.costos : [{ concepto: '', monto: '' }]);\n  const enc = r.encuesta;\n  const estrellas = (n, max = 5) => '★'.repeat(n) + '☆'.repeat(Math.max(0, max - n));\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal(); cargarSoporte();\">cerrar</button>\n    <h2 style=\"margin-bottom:2px;\">${escapeHtml(r.folio_txt)} · ${escapeHtml(r.cliente_nombre)}</h2>\n    <div style=\"display:flex; gap:10px; align-items:center; flex-wrap:wrap;\">${sopTipo(r.tipo_servicio)} ${sopChip(r.estado)}\n      <span style=\"font-size:11px; color:var(--muted);\">Creado ${escapeHtml((r.creado_en || '').replace('T', ' ').slice(0, 16))} por ${escapeHtml(r.creado_por_nombre || '—')}</span></div>\n    ${_pasosSoporte(r.estado)}\n    ${r.estado === 'cancelado' && r.motivo_cancelacion ? `<p style=\"color:#D8192F; font-size:13px;\">Motivo: ${escapeHtml(r.motivo_cancelacion)}</p>` : ''}\n    <div style=\"display:flex; gap:6px; flex-wrap:wrap; margin-bottom:12px;\">${acciones.join('')}</div>\n    ${!firmado ? `<div class=\"cv-caja\" style=\"border-color:#E6A014; font-size:13px; margin-bottom:12px;\">✍️ Falta que el cliente firme la orden. ${r.orden_enviada_en ? `Se le mandó el ${escapeHtml(r.orden_enviada_en.replace('T', ' ').slice(0, 16))}.` : 'Todavía no se le manda.'} En cuanto firme, pasa sola a <b>diagnóstico</b>.</div>`\n      : `<div class=\"cv-caja\" style=\"border-color:#2E9E6B; font-size:13px; margin-bottom:12px; display:flex; gap:12px; align-items:center;\">\n           ${r.firma_base64 ? `<img src=\"${r.firma_base64}\" style=\"height:46px; background:#fff; border-radius:4px;\" />` : ''}\n           <div>✔ Firmó <b>${escapeHtml(r.firma_nombre || '')}</b> el ${escapeHtml((r.firma_en || '').replace('T', ' ').slice(0, 16))} (${r.firma_origen === 'presencial' ? 'en persona' : 'desde el link'}).</div></div>`}\n\n    ${seccionColapsable('sop_datos', '👤 Cliente y equipo', `\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Tipo de servicio</label><select id=\"sd_tipo\"><option value=\"mantenimiento\" ${r.tipo_servicio === 'mantenimiento' ? 'selected' : ''}>Mantenimiento</option><option value=\"garantia\" ${r.tipo_servicio === 'garantia' ? 'selected' : ''}>Garantía</option></select></div>\n        <div class=\"field\"><label>Cliente</label><input id=\"sd_nombre\" value=\"${escapeHtml(r.cliente_nombre || '')}\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>WhatsApp / teléfono</label><input id=\"sd_tel\" value=\"${escapeHtml(r.cliente_telefono || '')}\" /></div>\n        <div class=\"field\"><label>Correo</label><input id=\"sd_email\" value=\"${escapeHtml(r.cliente_email || '')}\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Ciudad</label><input id=\"sd_ciudad\" value=\"${escapeHtml(r.cliente_ciudad || '')}\" /></div>\n        <div class=\"field\"><label>Dirección</label><input id=\"sd_dir\" value=\"${escapeHtml(r.cliente_direccion || '')}\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Tipo de unidad dental</label><input id=\"sd_unidad\" list=\"sd_l_unidad\" value=\"${escapeHtml(r.tipo_unidad || '')}\" />${_datalist('sd_l_unidad', sg.tipo_unidad)}</div>\n        <div class=\"field\"><label>Modelo</label><input id=\"sd_modelo\" list=\"sd_l_modelo\" value=\"${escapeHtml(r.modelo || '')}\" />${_datalist('sd_l_modelo', sg.modelo)}</div>\n      </div>\n      <div class=\"field\"><label>Número de serie</label><input id=\"sd_serie\" value=\"${escapeHtml(r.numero_serie || '')}\" /></div>\n      <div class=\"field\"><label>Problema reportado</label><textarea id=\"sd_problema\" rows=\"3\">${escapeHtml(r.problema || '')}</textarea></div>\n      ${firmado ? '<p style=\"font-size:11px; color:#E6A014;\">La orden ya está firmada: si cambias estos datos, el PDF de la orden cambia también.</p>' : ''}\n      ${cerrado ? '' : '<button class=\"secondary\" onclick=\"guardarDatosSoporte(this)\">Guardar datos</button>'}\n      <h4 style=\"margin:14px 0 4px;\">📎 Evidencia del cliente</h4>${listaEvid('reporte')}`, !firmado)}\n\n    ${seccionColapsable('sop_diag', '🔎 Diagnóstico y resolución (lo ve el cliente)', firmado ? `\n      <div class=\"field\"><label>Diagnóstico (sin costos)</label><textarea id=\"sd_diag\" rows=\"4\" placeholder=\"Qué se encontró y cuál es la causa técnica\">${escapeHtml(r.diagnostico || '')}</textarea></div>\n      <label style=\"font-size:12px; font-weight:700;\">Refacciones</label>\n      <table class=\"users\" style=\"font-size:12px;\"><thead><tr><th style=\"width:70px;\">Cant.</th><th>Descripción</th><th style=\"width:150px;\">No. de parte</th><th></th></tr></thead>\n        <tbody id=\"sd_refac\">${refac.map(x => `<tr>\n          <td><input class=\"rf_cant\" type=\"number\" min=\"0\" step=\"1\" value=\"${escapeHtml(x.cantidad ?? 1)}\" style=\"width:60px;\" /></td>\n          <td><input class=\"rf_desc\" value=\"${escapeHtml(x.descripcion || '')}\" /></td>\n          <td><input class=\"rf_parte\" value=\"${escapeHtml(x.numero_parte || '')}\" /></td>\n          <td><button class=\"secondary\" style=\"padding:2px 6px;\" onclick=\"this.closest('tr').remove()\">✕</button></td></tr>`).join('')}</tbody></table>\n      <button class=\"secondary\" style=\"font-size:12px; margin:4px 0 10px;\" onclick=\"agregarFilaSoporte('sd_refac')\">+ Refacción</button>\n      <h4 style=\"margin:8px 0 4px;\">📎 Evidencia del diagnóstico</h4>${listaEvid('diagnostico')}\n      <div class=\"field\" style=\"margin-top:10px;\"><label>Qué se le va a hacer (resolución)</label><textarea id=\"sd_resol\" rows=\"3\">${escapeHtml(r.resolucion || '')}</textarea></div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Paquetería</label><input id=\"sd_paq\" list=\"sd_l_paq\" value=\"${escapeHtml(r.paqueteria || '')}\" />${_datalist('sd_l_paq', [...(cat.paqueterias || []), ...(sg.paqueteria || [])])}</div>\n        <div class=\"field\"><label>¿Entrega en ocurre?</label>\n          <div style=\"display:flex; gap:14px; padding-top:8px;\">\n            <label><input style=\"width:auto;\" type=\"radio\" name=\"sd_ocurre\" value=\"si\" ${r.ocurre === true ? 'checked' : ''} /> Sí (recoge en la paquetería)</label>\n            <label><input style=\"width:auto;\" type=\"radio\" name=\"sd_ocurre\" value=\"no\" ${r.ocurre === false ? 'checked' : ''} /> No (a domicilio)</label>\n          </div></div>\n      </div>\n      ${cerrado ? '' : `<div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n        <button class=\"secondary\" onclick=\"guardarDiagnosticoSoporte(this)\">💾 Guardar diagnóstico</button>\n        <button class=\"primary\" onclick=\"enviarResolucionSoporte(this)\">📤 ${r.resolucion_enviada_en ? 'Guardar y reenviar' : 'Enviar resolución al cliente'} (con encuesta)</button></div>`}\n    ` : '<p style=\"font-size:13px; color:var(--muted);\">Se habilita cuando el cliente firme la orden de servicio.</p>', firmado && !r.resolucion_enviada_en)}\n\n    ${seccionColapsable('sop_interno', '🔒 Apartado interno (solo la empresa — no sale en ningún documento)', `\n      <label style=\"font-size:12px; font-weight:700;\">El problema fue por:</label>\n      <div style=\"display:flex; flex-wrap:wrap; gap:6px 16px; margin:6px 0 10px;\">\n        ${(cat.causas || []).map(c => `<label style=\"font-size:13px;\"><input style=\"width:auto;\" type=\"checkbox\" class=\"si_causa\" value=\"${escapeHtml(c)}\" ${(i.causas || []).includes(c) ? 'checked' : ''} /> ${escapeHtml(c)}</label>`).join('')}\n      </div>\n      <div class=\"field\"><label>Si es \"Otro\", ¿cuál?</label><input id=\"si_otro\" value=\"${escapeHtml(i.causa_otro || '')}\" /></div>\n      <div class=\"field\"><label>¿Qué causa la falla?</label><textarea id=\"si_falla\" rows=\"3\" placeholder=\"Causa raíz: lote, proveedor, pieza, instalación, transporte…\">${escapeHtml(i.causa_falla || '')}</textarea></div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Distribuidor que vendió la unidad / equipo</label><input id=\"si_dist\" list=\"si_l_dist\" value=\"${escapeHtml(i.distribuidor || '')}\" />${_datalist('si_l_dist', sg.distribuidor)}</div>\n        <div class=\"field\"><label>Método de envío</label><input id=\"si_metodo\" value=\"${escapeHtml(i.metodo_envio || '')}\" placeholder=\"ej. Paquetería, flete propio, entrega directa\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Empresa de paquetería</label><input id=\"si_paqnom\" list=\"si_l_paq\" value=\"${escapeHtml(i.paqueteria_nombre || '')}\" />${_datalist('si_l_paq', [...(cat.paqueterias || []), ...(sg.paqueteria_nombre || [])])}</div>\n        <div class=\"field\"><label>Tipo de paquetería</label><select id=\"si_paqtipo\"><option value=\"\">—</option>${(cat.tipos_paqueteria || []).map(t => `<option ${i.paqueteria_tipo === t ? 'selected' : ''}>${escapeHtml(t)}</option>`).join('')}</select></div>\n      </div>\n      <div class=\"field\"><label>Guía</label><input id=\"si_guia\" value=\"${escapeHtml(i.guia || '')}\" /></div>\n      <label style=\"font-size:12px; font-weight:700;\">Costos que le salieron a la empresa</label>\n      <table class=\"users\" style=\"font-size:12px;\"><thead><tr><th>Concepto</th><th style=\"width:140px;\">Monto</th><th></th></tr></thead>\n        <tbody id=\"si_costos\">${costos.map(c => `<tr>\n          <td><input class=\"ct_conc\" value=\"${escapeHtml(c.concepto || '')}\" placeholder=\"ej. Refacción, envío, viáticos, mano de obra\" /></td>\n          <td><input class=\"ct_monto\" type=\"number\" min=\"0\" step=\"0.01\" value=\"${escapeHtml(c.monto ?? '')}\" oninput=\"totalCostosSoporte()\" /></td>\n          <td><button class=\"secondary\" style=\"padding:2px 6px;\" onclick=\"this.closest('tr').remove(); totalCostosSoporte();\">✕</button></td></tr>`).join('')}</tbody>\n        <tfoot><tr><td style=\"text-align:right; font-weight:800;\">Total</td><td id=\"si_total\" style=\"font-weight:800;\">${fmtPesos(i.costo_total || 0)}</td><td></td></tr></tfoot></table>\n      <button class=\"secondary\" style=\"font-size:12px; margin:4px 0 10px;\" onclick=\"agregarFilaSoporte('si_costos')\">+ Costo</button>\n      <div class=\"field\"><label>Notas internas</label><textarea id=\"si_notas\" rows=\"2\">${escapeHtml(i.notas || '')}</textarea></div>\n      ${cerrado ? '' : '<button class=\"secondary\" onclick=\"guardarInternoSoporte(this)\">🔒 Guardar apartado interno</button>'}\n    `, false)}\n\n    ${enc ? seccionColapsable('sop_enc', '⭐ Encuesta de satisfacción', `\n      <table class=\"users\" style=\"font-size:13px;\">\n        <tr><td>Satisfacción con el producto</td><td style=\"color:#E6A014; font-size:16px;\">${estrellas(enc.satisfaccion_producto)}</td></tr>\n        <tr><td>Atención de soporte</td><td style=\"color:#E6A014; font-size:16px;\">${estrellas(enc.atencion)}</td></tr>\n        <tr><td>Rapidez</td><td style=\"color:#E6A014; font-size:16px;\">${estrellas(enc.rapidez)}</td></tr>\n        <tr><td>¿Nos recomendaría? (0–10)</td><td><b>${enc.recomendaria}</b></td></tr>\n        ${enc.comentarios ? `<tr><td>Comentarios</td><td>${escapeHtml(enc.comentarios)}</td></tr>` : ''}\n      </table>\n      <p style=\"font-size:11px; color:var(--muted);\">Contestada el ${escapeHtml((r.encuesta_en || '').replace('T', ' ').slice(0, 16))}</p>`, true) : ''}\n\n    ${seccionColapsable('sop_hist', '🕑 Historial', r.historial.map(h => `\n      <div style=\"font-size:12px; padding:4px 0; border-bottom:1px dashed var(--line);\"><b>${escapeHtml((h.creado_en || '').replace('T', ' ').slice(0, 16))}</b> — ${escapeHtml(h.texto)}${h.usuario_nombre ? ` <span style=\"color:var(--muted);\">(${escapeHtml(h.usuario_nombre)})</span>` : ''}</div>`).join(''), false)}\n    <div id=\"sd_error\" class=\"error-msg\"></div>`;\n  cargarMiniaturasSoporte();\n}\n\nasync function cargarMiniaturasSoporte() {\n  const r = SOP.actual;\n  for (const el of document.querySelectorAll('.sop-thumb')) {\n    if (!el.dataset.tipo.startsWith('image')) continue;\n    try {\n      const e = await api(`/api/soporte/${r.id}/evidencias/${el.dataset.id}`);\n      if (SOP.actual !== r) return;\n      el.innerHTML = `<img src=\"${e.data || e.url}\" style=\"width:100%; height:100%; object-fit:cover;\" />`;\n    } catch (e) { /* se queda el ícono */ }\n  }\n}\n\nasync function verEvidenciaSoporte(eid) {\n  try {\n    const e = await api(`/api/soporte/${SOP.actual.id}/evidencias/${eid}`);\n    if (e.url) { window.open(e.url, '_blank'); return; }\n    window.open(_dataURItoBlobUrl(e.data), '_blank');\n  } catch (err) { alert(err.message); }\n}\n\nasync function agregarEvidenciaSoporte(input, etapa) {\n  const archivos = [...input.files]; input.value = '';\n  if (!archivos.length) return;\n  const err = document.getElementById('sd_error');\n  err.textContent = 'Subiendo…';\n  await subirEvidenciasSoporte(SOP.actual.id, archivos, etapa, err);\n  err.textContent = '';\n  await abrirReporteSoporte(SOP.actual.id);\n}\n\nasync function borrarEvidenciaSoporte(eid) {\n  if (!confirm('¿Quitar esta evidencia?')) return;\n  try { await api(`/api/soporte/${SOP.actual.id}/evidencias/${eid}`, { method: 'DELETE' }); await abrirReporteSoporte(SOP.actual.id); }\n  catch (e) { alert(e.message); }\n}\n\nfunction agregarFilaSoporte(tbodyId) {\n  const tb = document.getElementById(tbodyId);\n  const tr = document.createElement('tr');\n  tr.innerHTML = tbodyId === 'sd_refac'\n    ? `<td><input class=\"rf_cant\" type=\"number\" min=\"0\" step=\"1\" value=\"1\" style=\"width:60px;\" /></td><td><input class=\"rf_desc\" /></td><td><input class=\"rf_parte\" /></td><td><button class=\"secondary\" style=\"padding:2px 6px;\" onclick=\"this.closest('tr').remove()\">✕</button></td>`\n    : `<td><input class=\"ct_conc\" /></td><td><input class=\"ct_monto\" type=\"number\" min=\"0\" step=\"0.01\" oninput=\"totalCostosSoporte()\" /></td><td><button class=\"secondary\" style=\"padding:2px 6px;\" onclick=\"this.closest('tr').remove(); totalCostosSoporte();\">✕</button></td>`;\n  tb.appendChild(tr);\n}\n\nfunction totalCostosSoporte() {\n  const t = [...document.querySelectorAll('#si_costos .ct_monto')].reduce((s, x) => s + (parseFloat(x.value) || 0), 0);\n  document.getElementById('si_total').textContent = fmtPesos(t);\n}\n\n// Todo lo capturado en pantalla (datos, diagnóstico e interno): cualquier botón de\n// guardar se lleva todo, para no perder lo escrito en otra sección al refrescar.\nfunction _cuerpoCompletoSoporte() {\n  const c = {};\n  if (document.getElementById('sd_nombre')) Object.assign(c, _cuerpoDatosSoporte());\n  if (document.getElementById('sd_diag')) Object.assign(c, _cuerpoDiagnostico());\n  if (document.getElementById('si_falla')) c.interno = _cuerpoInternoSoporte();\n  return c;\n}\n\nasync function _guardarSoporte(btn, cuerpo, mensaje) {\n  cuerpo = { ..._cuerpoCompletoSoporte(), ...cuerpo };\n  const err = document.getElementById('sd_error'); err.textContent = '';\n  let ok = false;\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      SOP.actual = await api(`/api/soporte/${SOP.actual.id}`, { method: 'PUT', body: JSON.stringify(cuerpo) });\n      if (mensaje) mostrarExito(mensaje);\n      ok = true;\n    } catch (e) { err.textContent = e.message; }\n  });\n  return ok;\n}\n\nfunction _cuerpoDatosSoporte() {\n  const v = (id) => document.getElementById(id).value.trim();\n  return { tipo_servicio: v('sd_tipo'), cliente_nombre: v('sd_nombre'), cliente_telefono: v('sd_tel') || null,\n    cliente_email: v('sd_email') || null, cliente_ciudad: v('sd_ciudad') || null, cliente_direccion: v('sd_dir') || null,\n    tipo_unidad: v('sd_unidad') || null, modelo: v('sd_modelo') || null, numero_serie: v('sd_serie').toUpperCase() || null,\n    problema: v('sd_problema') };\n}\n\nfunction guardarDatosSoporte(btn) {\n  _guardarSoporte(btn, {}, 'Datos guardados').then(ok => ok && pintarReporteSoporte());\n}\n\nfunction _cuerpoDiagnostico() {\n  const oc = (document.querySelector('input[name=\"sd_ocurre\"]:checked') || {}).value;\n  return {\n    diagnostico: document.getElementById('sd_diag').value.trim() || null,\n    refacciones: [...document.querySelectorAll('#sd_refac tr')].map(tr => ({\n      cantidad: tr.querySelector('.rf_cant').value, descripcion: tr.querySelector('.rf_desc').value.trim(),\n      numero_parte: tr.querySelector('.rf_parte').value.trim() })).filter(x => x.descripcion),\n    resolucion: document.getElementById('sd_resol').value.trim() || null,\n    paqueteria: document.getElementById('sd_paq').value.trim() || null,\n    ocurre: oc === 'si' ? true : (oc === 'no' ? false : null),\n  };\n}\n\nfunction guardarDiagnosticoSoporte(btn) {\n  _guardarSoporte(btn, {}, 'Diagnóstico guardado').then(ok => ok && pintarReporteSoporte());\n}\n\nasync function enviarResolucionSoporte(btn) {\n  const c = _cuerpoDiagnostico();\n  const err = document.getElementById('sd_error');\n  if (!c.diagnostico || !c.resolucion) { err.textContent = 'Captura el diagnóstico y qué se le va a hacer.'; return; }\n  if (!(await _guardarSoporte(btn, c))) return;\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      SOP.actual = await api(`/api/soporte/${SOP.actual.id}/enviar-resolucion`, { method: 'POST' });\n      pintarReporteSoporte();\n      whatsappSoporte('resolucion');\n    } catch (e) { err.textContent = e.message; }\n  });\n}\n\nfunction _cuerpoInternoSoporte() {\n  return {\n    causas: [...document.querySelectorAll('.si_causa:checked')].map(x => x.value),\n    causa_otro: document.getElementById('si_otro').value.trim(), causa_falla: document.getElementById('si_falla').value.trim(),\n    distribuidor: document.getElementById('si_dist').value.trim(), metodo_envio: document.getElementById('si_metodo').value.trim(),\n    paqueteria_nombre: document.getElementById('si_paqnom').value.trim(), paqueteria_tipo: document.getElementById('si_paqtipo').value,\n    guia: document.getElementById('si_guia').value.trim(), notas: document.getElementById('si_notas').value.trim(),\n    costos: [...document.querySelectorAll('#si_costos tr')].map(tr => ({ concepto: tr.querySelector('.ct_conc').value.trim(), monto: tr.querySelector('.ct_monto').value })),\n  };\n}\n\nfunction guardarInternoSoporte(btn) {\n  _guardarSoporte(btn, {}, 'Apartado interno guardado').then(ok => ok && pintarReporteSoporte());\n}\n\nasync function pdfSoporte(cual) {\n  const r = SOP.actual;\n  try {\n    const resp = await fetch(`${API}/api/soporte/${r.id}/${cual}.pdf?liga=${encodeURIComponent(sopLiga(r))}`, { headers: headers(false) });\n    if (!resp.ok) throw new Error('No se pudo generar el PDF');\n    const blob = await resp.blob();\n    const nombre = `${cual === 'orden' ? 'Orden_servicio' : 'Diagnostico'}_${r.folio_txt}.pdf`;\n    const archivo = new File([blob], nombre, { type: 'application/pdf' });\n    if (navigator.canShare && navigator.canShare({ files: [archivo] }) && confirm('¿Compartir el PDF (WhatsApp, correo…)? Cancelar = solo abrirlo.')) {\n      await navigator.share({ files: [archivo], title: nombre });\n    } else {\n      window.open(URL.createObjectURL(blob), '_blank');\n    }\n  } catch (e) { if (e.name !== 'AbortError') alert(e.message); }\n}\n\nfunction whatsappSoporte(cual) {\n  const r = SOP.actual;\n  const empresa = META.empresa_nombre || '';\n  const texto = cual === 'orden'\n    ? `Hola ${r.cliente_nombre}, te saluda Soporte Técnico de ${empresa}. Generamos tu orden de servicio ${r.folio_txt} (${r.tipo_servicio === 'garantia' ? 'garantía' : 'mantenimiento'}${r.numero_serie ? ', serie ' + r.numero_serie : ''}). Por favor revísala y fírmala aquí desde tu celular: ${sopLiga(r)}`\n    : `Hola ${r.cliente_nombre}, ya tenemos el diagnóstico de tu equipo (orden ${r.folio_txt}). Aquí puedes ver el diagnóstico, qué se le va a hacer y el envío, y contestar una encuesta muy corta: ${sopLiga(r)}`;\n  const tel = _telWhatsApp(r.cliente_telefono);\n  window.open(`https://wa.me/${tel}?text=${encodeURIComponent(texto)}`, '_blank');\n  if (cual === 'orden') api(`/api/soporte/${r.id}/orden-enviada`, { method: 'POST' }).then(() => abrirReporteSoporte(r.id)).catch(() => {});\n}\n\nfunction copiarLigaSoporte() {\n  navigator.clipboard.writeText(sopLiga(SOP.actual)).then(() => mostrarExito('Link copiado: pégalo en el chat del cliente'));\n}\n\nasync function cambiarEstadoSoporte(estado) {\n  let texto = null;\n  if (estado === 'cancelado') { texto = prompt('Motivo de la cancelación:'); if (!texto) return; }\n  else if (estado === 'enviado') { texto = prompt('Guía o nota del envío (opcional):', (SOP.actual.interno || {}).guia || ''); if (texto === null) return; }\n  else if (estado === 'cerrado' && !confirm('¿Cerrar el reporte?')) return;\n  try {\n    SOP.actual = await api(`/api/soporte/${SOP.actual.id}/estado`, { method: 'POST', body: JSON.stringify({ estado, texto }) });\n    pintarReporteSoporte();\n  } catch (e) { alert(e.message); }\n}\n\n// Firma en persona (en esta pantalla)\nlet SOP_FIRMA = { ctx: null, vacia: true, pintando: false };\nfunction abrirFirmaPresencialSoporte() {\n  const r = SOP.actual;\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"pintarReporteSoporte()\">regresar</button>\n    <h2>✍️ Firma del cliente — ${escapeHtml(r.folio_txt)}</h2>\n    <p style=\"font-size:12px; color:var(--muted);\">Que el cliente revise la orden (📄) y firme aquí con el dedo o el mouse.</p>\n    <button class=\"secondary\" onclick=\"pdfSoporte('orden')\">📄 Ver orden de servicio</button>\n    <div class=\"field\" style=\"margin-top:10px;\"><label>Nombre de quien firma</label><input id=\"sf_nombre\" value=\"${escapeHtml(r.cliente_nombre)}\" /></div>\n    <canvas id=\"sf_canvas\" width=\"600\" height=\"200\" style=\"width:100%; max-width:600px; background:#fff; border:2px dashed #999; border-radius:6px; touch-action:none;\"></canvas>\n    <div style=\"display:flex; gap:8px; margin-top:8px;\"><button class=\"secondary\" onclick=\"limpiarFirmaSoporte()\">Borrar</button>\n      <button class=\"primary\" style=\"flex:1;\" onclick=\"guardarFirmaPresencialSoporte(this)\">Firmar orden</button></div>\n    <div id=\"sf_error\" class=\"error-msg\"></div>`;\n  const cv = document.getElementById('sf_canvas');\n  SOP_FIRMA.ctx = cv.getContext('2d');\n  limpiarFirmaSoporte();\n  const pos = (e) => { const b = cv.getBoundingClientRect(); const t = e.touches ? e.touches[0] : e; return { x: (t.clientX - b.left) * cv.width / b.width, y: (t.clientY - b.top) * cv.height / b.height }; };\n  const ini = (e) => { e.preventDefault(); SOP_FIRMA.pintando = true; const p = pos(e); SOP_FIRMA.ctx.beginPath(); SOP_FIRMA.ctx.moveTo(p.x, p.y); };\n  const mov = (e) => { if (!SOP_FIRMA.pintando) return; e.preventDefault(); SOP_FIRMA.vacia = false; const p = pos(e); SOP_FIRMA.ctx.lineTo(p.x, p.y); SOP_FIRMA.ctx.stroke(); };\n  const fin = () => { SOP_FIRMA.pintando = false; };\n  cv.addEventListener('mousedown', ini); cv.addEventListener('mousemove', mov); window.addEventListener('mouseup', fin);\n  cv.addEventListener('touchstart', ini, { passive: false }); cv.addEventListener('touchmove', mov, { passive: false }); cv.addEventListener('touchend', fin);\n}\n\nfunction limpiarFirmaSoporte() {\n  const cv = document.getElementById('sf_canvas'), c = SOP_FIRMA.ctx;\n  c.fillStyle = '#fff'; c.fillRect(0, 0, cv.width, cv.height);\n  c.strokeStyle = '#111'; c.lineWidth = 2.6; c.lineCap = 'round'; c.lineJoin = 'round';\n  SOP_FIRMA.vacia = true;\n}\n\nasync function guardarFirmaPresencialSoporte(btn) {\n  const err = document.getElementById('sf_error');\n  const nombre = document.getElementById('sf_nombre').value.trim();\n  if (nombre.length < 3) { err.textContent = 'Escribe el nombre de quien firma.'; return; }\n  if (SOP_FIRMA.vacia) { err.textContent = 'Falta la firma.'; return; }\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      SOP.actual = await api(`/api/soporte/${SOP.actual.id}/firmar`, { method: 'POST', body: JSON.stringify({\n        nombre, firma_base64: document.getElementById('sf_canvas').toDataURL('image/png') }) });\n      mostrarExito('Orden firmada. Pasa a diagnóstico.');\n      pintarReporteSoporte();\n    } catch (e) { err.textContent = e.message; }\n  });\n}\n\n// ---- Análisis para la empresa ----\nasync function abrirAnalisisSoporte(desde = '', hasta = '') {\n  document.getElementById('modalContent').innerHTML = `<button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button><h2>📊 Análisis de soporte</h2><p>Calculando…</p>`;\n  abrirModal();\n  let a;\n  try { a = await api(`/api/soporte/analisis?desde=${desde}&hasta=${hasta}`); }\n  catch (e) { document.getElementById('modalContent').innerHTML += `<p class=\"error-msg\">${escapeHtml(e.message)}</p>`; return; }\n  const tablaConteo = (titulo, filas, extra = null) => `\n    <div style=\"flex:1; min-width:240px;\"><h4 style=\"margin:10px 0 4px;\">${titulo}</h4>\n      <table class=\"users\" style=\"font-size:12px;\">${filas.map(([k, n]) => `<tr><td>${escapeHtml(k)}</td><td style=\"text-align:right;\"><b>${n}</b></td>${extra ? `<td style=\"text-align:right;\">${fmtPesos(extra[k] || 0)}</td>` : ''}</tr>`).join('') || '<tr><td>—</td></tr>'}</table></div>`;\n  const costoCausa = Object.fromEntries(a.costo_por_causa);\n  const p = a.encuesta_promedios || {};\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button>\n    <h2>📊 Análisis de soporte</h2>\n    <div style=\"display:flex; gap:8px; align-items:center; flex-wrap:wrap; margin-bottom:10px;\">\n      Del <input type=\"date\" id=\"sa_desde\" value=\"${desde}\" style=\"width:auto;\" /> al <input type=\"date\" id=\"sa_hasta\" value=\"${hasta}\" style=\"width:auto;\" />\n      <button class=\"secondary\" onclick=\"abrirAnalisisSoporte(document.getElementById('sa_desde').value, document.getElementById('sa_hasta').value)\">Ver</button>\n    </div>\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n      <div class=\"cv-caja\" style=\"flex:1; min-width:140px;\"><div style=\"font-size:11px; color:var(--muted);\">REPORTES</div><div style=\"font-size:22px; font-weight:800;\">${a.total}</div></div>\n      <div class=\"cv-caja\" style=\"flex:1; min-width:140px;\"><div style=\"font-size:11px; color:var(--muted);\">COSTO PARA LA EMPRESA</div><div style=\"font-size:22px; font-weight:800;\">${fmtPesos(a.costo_total)}</div></div>\n      <div class=\"cv-caja\" style=\"flex:1; min-width:140px;\"><div style=\"font-size:11px; color:var(--muted);\">ENCUESTAS</div><div style=\"font-size:22px; font-weight:800;\">${a.encuestas}</div>\n        <div style=\"font-size:11px;\">Producto ${p.satisfaccion_producto ?? '—'}/5 · Atención ${p.atencion ?? '—'}/5 · Rapidez ${p.rapidez ?? '—'}/5 · Recomienda ${p.recomendaria ?? '—'}/10</div></div>\n    </div>\n    <div style=\"display:flex; gap:12px; flex-wrap:wrap;\">\n      ${tablaConteo('Causa del problema (reportes · costo)', a.por_causa, costoCausa)}\n      ${tablaConteo('Distribuidor que vendió', a.por_distribuidor)}\n      ${tablaConteo('Tipo de unidad dental', a.por_unidad)}\n      ${tablaConteo('Paquetería', a.por_paqueteria)}\n      ${tablaConteo('Tipo de servicio', a.por_tipo)}\n      ${tablaConteo('Estatus', a.por_estado)}\n    </div>`;\n}\n\n// ---- Personalización de términos (por empresa) ----\n"
