NUEVOS = {
 "backend/soporte_pdf.py": "# -*- coding: utf-8 -*-\n\"\"\"PDFs del módulo de Soporte técnico (Peymar): orden de servicio (con la firma\ndel cliente) y diagnóstico / resolución para el cliente. Llevan el logo de la\nempresa (Superadmin → logo). Nunca incluyen el apartado interno ni costos.\"\"\"\nimport base64\nfrom io import BytesIO\nfrom xml.sax.saxutils import escape\n\nfrom reportlab.lib import colors\nfrom reportlab.lib.enums import TA_CENTER\nfrom reportlab.lib.pagesizes import letter\nfrom reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet\nfrom reportlab.lib.units import cm\nfrom reportlab.lib.utils import ImageReader\nfrom reportlab.pdfgen import canvas as rl_canvas\nfrom reportlab.platypus import Image, KeepTogether, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle\n\nfrom minuta_ia import _fecha_corta, _fecha_larga, _fuentes\n\nTIPOS = {\"mantenimiento\": \"Mantenimiento\", \"garantia\": \"Garantía\"}\nAZUL = colors.HexColor(\"#0E4C92\")      # acento por default si la empresa no tiene color\nTINTA = colors.HexColor(\"#1B1B1D\")\nGRIS = colors.HexColor(\"#5B5D62\")\nLINEA = colors.HexColor(\"#D9D4CF\")\nCLARO = colors.HexColor(\"#F4F6FA\")\nANCHO = letter[0] - 3.6 * cm\n\n\ndef _logo_de(empresa):\n    \"\"\"Solo el logo de ESTA empresa (Superadmin → logo); sin logo, va su nombre en texto.\"\"\"\n    datos = (empresa or {}).get(\"logo_base64\") if isinstance(empresa, dict) else None\n    if not datos:\n        return None\n    try:\n        return base64.b64decode(datos.split(\",\", 1)[1] if \",\" in datos else datos)\n    except Exception:\n        return None\n\n\ndef folio_txt(r):\n    return f\"SOP-{int(r['folio']):06d}\"\n\n\ndef _acento(empresa):\n    c = (empresa or {}).get(\"color_acento\") if isinstance(empresa, dict) else None\n    try:\n        return colors.HexColor(c) if c and c.startswith(\"#\") and len(c) in (4, 7) else AZUL\n    except Exception:\n        return AZUL\n\n\ndef _estilos(acento):\n    F, FB, _ = _fuentes()\n    st = getSampleStyleSheet()\n    base = ParagraphStyle(\"b\", parent=st[\"BodyText\"], fontName=F, fontSize=9.6, leading=13.4, textColor=TINTA)\n    return {\n        \"base\": base,\n        \"chico\": ParagraphStyle(\"c\", parent=base, fontSize=8, leading=10.5, textColor=GRIS),\n        \"et\": ParagraphStyle(\"e\", parent=base, fontName=FB, fontSize=7.4, leading=9, textColor=GRIS),\n        \"val\": ParagraphStyle(\"v\", parent=base, fontName=FB, fontSize=9.6, leading=12),\n        \"celda\": ParagraphStyle(\"ce\", parent=base, fontSize=8.8, leading=11.4),\n        \"encab\": ParagraphStyle(\"en\", parent=base, fontName=FB, fontSize=8.2, leading=10.5, textColor=colors.white),\n        \"titulo\": ParagraphStyle(\"t\", parent=base, fontName=FB, fontSize=16, leading=19),\n        \"sub\": ParagraphStyle(\"s\", parent=base, fontName=FB, fontSize=9, leading=11, textColor=acento),\n        \"sec\": ParagraphStyle(\"se\", parent=base, fontName=FB, fontSize=9.6, leading=12),\n        \"F\": F, \"FB\": FB,\n    }\n\n\ndef _e(t):\n    return escape(str(t if t is not None else \"\"))\n\n\ndef _imagen(datos_b64, max_w, max_h):\n    try:\n        raw = base64.b64decode(datos_b64.split(\",\", 1)[1] if \",\" in datos_b64 else datos_b64)\n        iw, ih = ImageReader(BytesIO(raw)).getSize()\n        k = min(max_w / iw, max_h / ih, 1e9)\n        return Image(BytesIO(raw), width=iw * k, height=ih * k)\n    except Exception:\n        return None\n\n\nclass _Doc:\n    \"\"\"Encabezado (logo | título | folio), secciones numeradas y pie con 'Página X de Y'.\"\"\"\n\n    def __init__(self, empresa, titulo, r):\n        self.empresa = empresa or {}\n        self.acento = _acento(self.empresa)\n        self.s = _estilos(self.acento)\n        self.titulo = titulo\n        self.r = r\n        self.h = []\n        self.n = 0\n        self.nombre_empresa = (self.empresa.get(\"nombre\") if isinstance(self.empresa, dict) else str(self.empresa)) or \"\"\n\n    def encabezado(self, fecha):\n        s = self.s\n        logo = _logo_de(self.empresa)\n        celda_logo = Paragraph(_e(self.nombre_empresa), ParagraphStyle(\"ln\", parent=s[\"titulo\"], fontSize=13, leading=15))\n        if logo:\n            try:\n                iw, ih = ImageReader(BytesIO(logo)).getSize()\n                w = 4.3 * cm\n                hh = w * ih / iw\n                if hh > 1.9 * cm:\n                    hh = 1.9 * cm\n                    w = hh * iw / ih\n                celda_logo = Image(BytesIO(logo), width=w, height=hh)\n            except Exception:\n                pass\n        blanco = lambda st, **k: ParagraphStyle(\"x\", parent=st, textColor=colors.white, alignment=TA_CENTER, **k)\n        caja = Table([[Paragraph(\"FOLIO\", blanco(s[\"et\"]))],\n                      [Paragraph(_e(folio_txt(self.r)), blanco(s[\"val\"], fontSize=11))],\n                      [Paragraph(_e(_fecha_corta(fecha)), blanco(s[\"chico\"]))]], colWidths=[3.4 * cm])\n        caja.setStyle(TableStyle([(\"BACKGROUND\", (0, 0), (-1, -1), self.acento), (\"TOPPADDING\", (0, 0), (-1, -1), 2),\n                                  (\"BOTTOMPADDING\", (0, 0), (-1, -1), 2)]))\n        cab = Table([[celda_logo, [Paragraph(_e(self.titulo), s[\"titulo\"]), Spacer(1, 2),\n                                   Paragraph(_e(self.nombre_empresa).upper() + \" · SOPORTE TÉCNICO\", s[\"sub\"])], caja]],\n                    colWidths=[4.8 * cm, ANCHO - 4.8 * cm - 3.6 * cm, 3.6 * cm])\n        cab.setStyle(TableStyle([(\"VALIGN\", (0, 0), (-1, -1), \"MIDDLE\"), (\"LEFTPADDING\", (0, 0), (-1, -1), 0),\n                                 (\"RIGHTPADDING\", (0, 0), (-1, -1), 0), (\"LINEBELOW\", (0, 0), (-1, 0), 2, self.acento),\n                                 (\"BOTTOMPADDING\", (0, 0), (-1, 0), 8)]))\n        self.h += [cab, Spacer(1, 10)]\n\n    def seccion(self, texto, devolver=False):\n        self.n += 1\n        t = Table([[Paragraph(f\"{self.n}.&nbsp;&nbsp;{_e(texto.upper())}\", self.s[\"sec\"])]], colWidths=[ANCHO])\n        t.setStyle(TableStyle([(\"BACKGROUND\", (0, 0), (-1, -1), CLARO), (\"LINEBEFORE\", (0, 0), (0, -1), 3.2, self.acento),\n                               (\"LEFTPADDING\", (0, 0), (-1, -1), 8), (\"TOPPADDING\", (0, 0), (-1, -1), 5),\n                               (\"BOTTOMPADDING\", (0, 0), (-1, -1), 5)]))\n        if devolver:\n            return [Spacer(1, 10), t, Spacer(1, 5)]\n        self.h += [Spacer(1, 10), t, Spacer(1, 5)]\n\n    def datos(self, pares):\n        \"\"\"pares: [(etiqueta, valor), ...] en 2 columnas.\"\"\"\n        s = self.s\n        filas = []\n        for i in range(0, len(pares), 2):\n            fila = []\n            for et, val in pares[i:i + 2]:\n                fila += [Paragraph(_e(et).upper(), s[\"et\"]), Paragraph(_e(val) if val not in (None, \"\") else \"—\", s[\"val\"])]\n            while len(fila) < 4:\n                fila.append(\"\")\n            filas.append(fila)\n        t = Table(filas, colWidths=[3.1 * cm, ANCHO / 2 - 3.1 * cm, 3.1 * cm, ANCHO / 2 - 3.1 * cm])\n        t.setStyle(TableStyle([(\"VALIGN\", (0, 0), (-1, -1), \"MIDDLE\"), (\"BOX\", (0, 0), (-1, -1), 0.6, LINEA),\n                               (\"INNERGRID\", (0, 0), (-1, -1), 0.4, LINEA),\n                               (\"BACKGROUND\", (0, 0), (0, -1), CLARO), (\"BACKGROUND\", (2, 0), (2, -1), CLARO),\n                               (\"TOPPADDING\", (0, 0), (-1, -1), 5), (\"BOTTOMPADDING\", (0, 0), (-1, -1), 5)]))\n        self.h.append(t)\n\n    def texto(self, t):\n        for parrafo in str(t or \"—\").split(\"\\n\"):\n            self.h.append(Paragraph(_e(parrafo) or \"&nbsp;\", self.s[\"base\"]))\n\n    def tabla(self, filas, anchos):\n        t = Table(filas, colWidths=anchos, repeatRows=1)\n        t.setStyle(TableStyle([(\"BACKGROUND\", (0, 0), (-1, 0), TINTA), (\"VALIGN\", (0, 0), (-1, -1), \"TOP\"),\n                               (\"LINEBELOW\", (0, 1), (-1, -1), 0.4, LINEA), (\"BOX\", (0, 0), (-1, -1), 0.5, LINEA),\n                               (\"ROWBACKGROUNDS\", (0, 1), (-1, -1), [colors.white, CLARO]),\n                               (\"TOPPADDING\", (0, 0), (-1, -1), 4), (\"BOTTOMPADDING\", (0, 0), (-1, -1), 4)]))\n        self.h.append(t)\n\n    def fotos(self, evidencias, max_fotos=6, titulo=None):\n        \"\"\"evidencias: [{archivo_base64, tipo, descripcion}] — solo imágenes, 3 por renglón.\"\"\"\n        imgs = []\n        for ev in evidencias:\n            if len(imgs) >= max_fotos:\n                break\n            if (ev.get(\"tipo\") or \"\").startswith(\"image\") and ev.get(\"archivo_base64\"):\n                im = _imagen(ev[\"archivo_base64\"], ANCHO / 3 - 0.4 * cm, 4.6 * cm)\n                if im:\n                    imgs.append([im, Paragraph(_e(ev.get(\"descripcion\") or \"\"), self.s[\"chico\"])])\n        if not imgs:\n            return False\n        filas = []\n        for i in range(0, len(imgs), 3):\n            grupo = imgs[i:i + 3]\n            filas.append([g[0] for g in grupo] + [\"\"] * (3 - len(grupo)))\n            filas.append([g[1] for g in grupo] + [\"\"] * (3 - len(grupo)))\n        t = Table(filas, colWidths=[ANCHO / 3] * 3)\n        t.setStyle(TableStyle([(\"ALIGN\", (0, 0), (-1, -1), \"CENTER\"), (\"VALIGN\", (0, 0), (-1, -1), \"MIDDLE\")]))\n        self.h.append(KeepTogether((self.seccion(titulo, devolver=True) if titulo else []) + [t]))\n        return True\n\n    def construir(self, pie):\n        acento = self.acento\n        F = self.s[\"F\"]\n\n        class _Lienzo(rl_canvas.Canvas):\n            def __init__(self, *a, **k):\n                super().__init__(*a, **k)\n                self._paginas = []\n\n            def showPage(self):\n                self._paginas.append(dict(self.__dict__))\n                self._startPage()\n\n            def save(self):\n                total = len(self._paginas)\n                for estado in self._paginas:\n                    self.__dict__.update(estado)\n                    self.setStrokeColor(acento)\n                    self.setLineWidth(0.8)\n                    self.line(1.8 * cm, 1.35 * cm, letter[0] - 1.8 * cm, 1.35 * cm)\n                    self.setFont(F, 7.5)\n                    self.setFillColor(GRIS)\n                    self.drawString(1.8 * cm, 0.95 * cm, pie)\n                    self.drawRightString(letter[0] - 1.8 * cm, 0.95 * cm, f\"Página {self._pageNumber} de {total}\")\n                    super().showPage()\n                super().save()\n\n        buf = BytesIO()\n        doc = SimpleDocTemplate(buf, pagesize=letter, leftMargin=1.8 * cm, rightMargin=1.8 * cm, topMargin=1.5 * cm,\n                                bottomMargin=1.9 * cm, title=f\"{self.titulo} {folio_txt(self.r)}\", author=self.nombre_empresa)\n        doc.build(self.h, canvasmaker=_Lienzo)\n        return buf.getvalue()\n\n\ndef _datos_equipo(d, r):\n    d.datos([(\"Tipo de unidad dental\", r.get(\"tipo_unidad\")), (\"Modelo\", r.get(\"modelo\")),\n             (\"Número de serie\", r.get(\"numero_serie\")), (\"Tipo de servicio\", TIPOS.get(r.get(\"tipo_servicio\"), r.get(\"tipo_servicio\")))])\n\n\ndef _datos_cliente(d, r):\n    d.datos([(\"Cliente\", r.get(\"cliente_nombre\")), (\"Teléfono\", r.get(\"cliente_telefono\")),\n             (\"Correo\", r.get(\"cliente_email\")), (\"Ciudad\", r.get(\"cliente_ciudad\")),\n             (\"Dirección\", r.get(\"cliente_direccion\"))])\n\n\ndef orden_servicio_pdf(r, empresa, evidencias, liga=None):\n    \"\"\"r: reporte (con firma si ya firmó). evidencias: las de la etapa 'reporte' con archivo_base64.\"\"\"\n    d = _Doc(empresa, \"ORDEN DE SERVICIO\", r)\n    fecha = r.get(\"creado_en\") or \"\"\n    d.encabezado(fecha)\n    d.datos([(\"Fecha\", _fecha_larga(fecha)), (\"Hora\", fecha[11:16] if len(fecha) >= 16 else \"\"),\n             (\"Tipo de servicio\", TIPOS.get(r.get(\"tipo_servicio\"), r.get(\"tipo_servicio\"))), (\"Atendió\", r.get(\"creado_por_nombre\"))])\n    d.seccion(\"Datos del cliente\")\n    _datos_cliente(d, r)\n    d.seccion(\"Equipo\")\n    _datos_equipo(d, r)\n    d.seccion(\"Problema reportado\")\n    d.texto(r.get(\"problema\"))\n    if evidencias:\n        if not d.fotos(evidencias, titulo=\"Evidencia enviada por el cliente\"):\n            d.seccion(\"Evidencia enviada por el cliente\")\n            d.texto(f\"{len(evidencias)} archivo(s) de evidencia (videos o documentos) en el expediente.\")\n        else:\n            otros = sum(1 for e in evidencias if not (e.get(\"tipo\") or \"\").startswith(\"image\"))\n            if otros:\n                d.h.append(Paragraph(f\"Además, {otros} video(s)/documento(s) en el expediente.\", d.s[\"chico\"]))\n    condiciones = d.seccion(\"Condiciones del servicio\", devolver=True) + [Paragraph(\n        \"El cliente autoriza a \" + _e(d.nombre_empresa or \"la empresa\") + \" a revisar y diagnosticar el equipo descrito. \"\n        \"El diagnóstico determinará la causa de la falla y la solución. \"\n        + (\"En servicios de garantía, la cobertura queda sujeta al dictamen técnico (no cubre mal uso, golpes, \"\n           \"instalación inadecuada ni piezas de desgaste). \" if r.get(\"tipo_servicio\") == \"garantia\" else\n           \"Cualquier costo se informa por separado antes de realizar trabajos adicionales. \")\n        + \"Con su firma, el cliente confirma que los datos y el problema reportado son correctos.\", d.s[\"chico\"])]\n    # Firma\n    s = d.s\n    if r.get(\"firma_base64\"):\n        im = _imagen(r[\"firma_base64\"], 6.5 * cm, 2.6 * cm)\n        origen = \"en persona\" if r.get(\"firma_origen\") == \"presencial\" else \"electrónicamente desde la liga enviada al cliente\"\n        bloque = [im or Spacer(1, 30),\n                  Table([[\"\"]], colWidths=[7 * cm], style=[(\"LINEABOVE\", (0, 0), (-1, -1), 0.8, TINTA)]),\n                  Paragraph(f\"<b>{_e(r.get('firma_nombre'))}</b>\", ParagraphStyle(\"fn\", parent=s[\"celda\"], alignment=TA_CENTER)),\n                  Paragraph(f\"Firmó {origen} el {_e(_fecha_larga(r.get('firma_en')))} a las {_e((r.get('firma_en') or '')[11:16])}\"\n                            + (f\" · IP {_e(r.get('firma_ip'))}\" if r.get(\"firma_ip\") and r.get(\"firma_origen\") != \"presencial\" else \"\"),\n                            ParagraphStyle(\"fo\", parent=s[\"chico\"], alignment=TA_CENTER))]\n    else:\n        bloque = [Spacer(1, 40), Table([[\"\"]], colWidths=[7 * cm], style=[(\"LINEABOVE\", (0, 0), (-1, -1), 0.8, TINTA)]),\n                  Paragraph(\"Nombre y firma de conformidad del cliente\", ParagraphStyle(\"fn\", parent=s[\"chico\"], alignment=TA_CENTER))]\n        if liga:\n            bloque.append(Paragraph(f\"Firma desde tu celular: {_e(liga)}\", ParagraphStyle(\"fl\", parent=s[\"chico\"], alignment=TA_CENTER)))\n    t = Table([[bloque]], colWidths=[ANCHO])\n    t.setStyle(TableStyle([(\"ALIGN\", (0, 0), (-1, -1), \"CENTER\")]))\n    d.h += [KeepTogether(condiciones + [Spacer(1, 14), t])]\n    return d.construir(f\"{d.nombre_empresa} · Orden de servicio {folio_txt(r)}\")\n\n\ndef resolucion_pdf(r, empresa, evidencias, liga_encuesta=None):\n    \"\"\"Diagnóstico y resolución para el cliente. SIN costos ni apartado interno.\"\"\"\n    d = _Doc(empresa, \"DIAGNÓSTICO Y RESOLUCIÓN\", r)\n    fecha = r.get(\"resolucion_enviada_en\") or r.get(\"actualizado_en\") or r.get(\"creado_en\") or \"\"\n    d.encabezado(fecha)\n    d.datos([(\"Fecha\", _fecha_larga(fecha)), (\"Orden de servicio\", f\"{folio_txt(r)} del {_fecha_corta(r.get('creado_en'))}\"),\n             (\"Cliente\", r.get(\"cliente_nombre\")), (\"Teléfono\", r.get(\"cliente_telefono\"))])\n    d.seccion(\"Equipo\")\n    _datos_equipo(d, r)\n    d.seccion(\"Problema reportado\")\n    d.texto(r.get(\"problema\"))\n    d.seccion(\"Diagnóstico\")\n    d.texto(r.get(\"diagnostico\"))\n    refacciones = [x for x in (r.get(\"refacciones\") or []) if (x.get(\"descripcion\") or \"\").strip()]\n    if refacciones:\n        d.seccion(\"Refacciones\")\n        s = d.s\n        filas = [[Paragraph(x, s[\"encab\"]) for x in (\"#\", \"Cantidad\", \"Descripción\", \"No. de parte\")]]\n        for i, x in enumerate(refacciones, 1):\n            filas.append([Paragraph(str(i), s[\"celda\"]), Paragraph(_e(x.get(\"cantidad\") or 1), s[\"celda\"]),\n                          Paragraph(_e(x.get(\"descripcion\")), s[\"celda\"]), Paragraph(_e(x.get(\"numero_parte\") or \"—\"), s[\"celda\"])])\n        d.tabla(filas, [0.8 * cm, 2 * cm, ANCHO - 0.8 * cm - 2 * cm - 4 * cm, 4 * cm])\n    d.seccion(\"Qué se va a hacer\")\n    d.texto(r.get(\"resolucion\"))\n    d.seccion(\"Envío\")\n    ocurre = r.get(\"ocurre\")\n    d.datos([(\"Paquetería\", r.get(\"paqueteria\")),\n             (\"Entrega en ocurre\", \"Sí — se recoge en la sucursal de la paquetería\" if ocurre else (\"No — entrega a domicilio\" if ocurre is False else \"\")),\n             (\"Dirección\", r.get(\"cliente_direccion\")), (\"Ciudad\", r.get(\"cliente_ciudad\"))])\n    if evidencias:\n        d.fotos(evidencias, titulo=\"Evidencia del diagnóstico\")\n    if liga_encuesta:\n        s = d.s\n        caja = Table([[Paragraph(\"<b>¿Cómo te fue con tu equipo y con nuestro servicio?</b><br/>\"\n                                 f\"Ayúdanos contestando una encuesta de 1 minuto: {_e(liga_encuesta)}\", s[\"base\"])]],\n                     colWidths=[ANCHO])\n        caja.setStyle(TableStyle([(\"BOX\", (0, 0), (-1, -1), 1, d.acento), (\"TOPPADDING\", (0, 0), (-1, -1), 8),\n                                  (\"BOTTOMPADDING\", (0, 0), (-1, -1), 8), (\"LEFTPADDING\", (0, 0), (-1, -1), 10)]))\n        d.h += [Spacer(1, 14), caja]\n    return d.construir(f\"{d.nombre_empresa} · Diagnóstico y resolución {folio_txt(r)}\")\n",
 "frontend/soporte_cliente.html": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n<title>Soporte técnico</title>\n<style>\n  :root { --acento: #0E4C92; --tinta: #16181d; --gris: #5b5d62; --linea: #e3e6ec; --fondo: #f4f6fa; --ok: #1f8a5b; }\n  * { box-sizing: border-box; }\n  body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; background: var(--fondo); color: var(--tinta); }\n  .barra { background: #fff; border-bottom: 3px solid var(--acento); padding: 14px 16px; display: flex; align-items: center; gap: 12px; }\n  .barra img { max-height: 46px; max-width: 160px; object-fit: contain; }\n  .barra .emp { font-weight: 800; font-size: 17px; }\n  .barra .sub { font-size: 12px; color: var(--gris); }\n  main { max-width: 640px; margin: 0 auto; padding: 16px 16px 40px; }\n  .tarjeta { background: #fff; border-radius: 14px; padding: 16px; margin-bottom: 14px; box-shadow: 0 1px 3px rgba(0,0,0,.06); }\n  h1 { font-size: 20px; margin: 0 0 4px; }\n  h2 { font-size: 15px; margin: 0 0 10px; color: var(--acento); text-transform: uppercase; letter-spacing: .03em; }\n  .folio { display: inline-block; background: var(--acento); color: #fff; font-weight: 800; font-size: 12px; border-radius: 8px; padding: 3px 9px; }\n  .estado { display: inline-block; font-size: 12px; font-weight: 700; color: var(--acento); background: rgba(14,76,146,.08); border-radius: 8px; padding: 3px 9px; margin-left: 6px; }\n  dl { display: grid; grid-template-columns: 130px 1fr; gap: 6px 10px; margin: 0; font-size: 14px; }\n  dt { color: var(--gris); font-size: 12px; text-transform: uppercase; padding-top: 2px; }\n  dd { margin: 0; font-weight: 600; }\n  p { line-height: 1.45; font-size: 15px; }\n  .boton { display: block; width: 100%; border: 0; border-radius: 12px; padding: 15px; font-size: 16px; font-weight: 800; cursor: pointer; text-align: center; text-decoration: none; }\n  .primario { background: var(--acento); color: #fff; }\n  .secundario { background: #fff; color: var(--acento); border: 2px solid var(--acento); }\n  .boton:disabled { opacity: .6; }\n  input[type=text], textarea { width: 100%; font-size: 16px; padding: 12px; border: 1px solid #cfd4dc; border-radius: 10px; font-family: inherit; }\n  canvas { width: 100%; height: 190px; background: #fff; border: 2px dashed #9aa3b2; border-radius: 12px; touch-action: none; display: block; }\n  .fila { display: flex; gap: 10px; margin-top: 10px; }\n  .fila > * { flex: 1; }\n  .ok { color: var(--ok); font-weight: 800; }\n  .error { color: #c62828; font-weight: 700; font-size: 14px; min-height: 18px; margin-top: 8px; }\n  table { width: 100%; border-collapse: collapse; font-size: 14px; }\n  td, th { text-align: left; padding: 7px 4px; border-bottom: 1px solid var(--linea); }\n  th { font-size: 11px; color: var(--gris); text-transform: uppercase; }\n  .estrellas { display: flex; gap: 6px; margin: 6px 0 14px; }\n  .estrellas button { flex: 1; font-size: 28px; background: #fff; border: 1px solid var(--linea); border-radius: 10px; padding: 6px 0; cursor: pointer; color: #c9ced8; }\n  .estrellas button.on { color: #f2a900; border-color: #f2a900; }\n  .nps { display: grid; grid-template-columns: repeat(11, 1fr); gap: 4px; margin: 6px 0 14px; }\n  .nps button { padding: 9px 0; font-size: 14px; font-weight: 700; border-radius: 8px; border: 1px solid var(--linea); background: #fff; cursor: pointer; }\n  .nps button.on { background: var(--acento); color: #fff; border-color: var(--acento); }\n  label.chk { display: flex; gap: 8px; align-items: flex-start; font-size: 14px; margin: 10px 0; }\n  .pie { text-align: center; font-size: 12px; color: var(--gris); margin-top: 20px; }\n  @media (max-width: 420px) { dl { grid-template-columns: 1fr; } dt { padding-top: 6px; } .nps button { font-size: 12px; padding: 8px 0; } }\n</style>\n</head>\n<body>\n<div class=\"barra\" id=\"barra\"><div class=\"emp\">Soporte técnico</div></div>\n<main id=\"contenido\"><div class=\"tarjeta\">Cargando…</div></main>\n\n<script>\nconst TOKEN = decodeURIComponent(location.pathname.split('/').filter(Boolean).pop() || '');\nconst API = `/api/publico/soporte/${encodeURIComponent(TOKEN)}`;\nlet D = null;\nconst esc = (t) => String(t ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst fecha = (iso) => { if (!iso) return ''; const d = new Date(iso); return isNaN(d) ? iso : d.toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' }); };\n\nasync function cargar() {\n  try {\n    const r = await fetch(API);\n    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || 'Este link no es válido.');\n    D = await r.json();\n  } catch (e) {\n    document.getElementById('contenido').innerHTML = `<div class=\"tarjeta\"><h1>No encontramos tu orden</h1><p>${esc(e.message)}</p></div>`;\n    return;\n  }\n  if (D.color && /^#[0-9a-f]{3,6}$/i.test(D.color)) document.documentElement.style.setProperty('--acento', D.color);\n  document.title = `${D.empresa || 'Soporte'} · ${D.folio}`;\n  document.getElementById('barra').innerHTML = `${D.logo ? `<img src=\"${D.logo}\" alt=\"\">` : ''}<div><div class=\"emp\">${esc(D.empresa || '')}</div><div class=\"sub\">Soporte técnico</div></div>`;\n  pintar();\n}\n\nfunction equipo() {\n  return `<dl>\n    <dt>Servicio</dt><dd>${esc(D.tipo_servicio)}</dd>\n    <dt>Equipo</dt><dd>${esc(D.tipo_unidad || '—')}${D.modelo ? ' · ' + esc(D.modelo) : ''}</dd>\n    <dt>No. de serie</dt><dd>${esc(D.numero_serie || '—')}</dd>\n    <dt>Fecha</dt><dd>${fecha(D.fecha)}</dd>\n  </dl>`;\n}\n\nfunction pintar() {\n  const c = document.getElementById('contenido');\n  let html = `<div class=\"tarjeta\"><span class=\"folio\">${esc(D.folio)}</span><span class=\"estado\">${esc(D.estado)}</span>\n    <h1 style=\"margin-top:10px;\">Hola, ${esc(D.cliente_nombre)}</h1>${equipo()}\n    <p style=\"margin-bottom:0;\"><b>Problema reportado:</b><br>${esc(D.problema).replace(/\\n/g, '<br>')}</p></div>`;\n  if (!D.firmada) {\n    html += `<div class=\"tarjeta\"><h2>1. Revisa tu orden de servicio</h2>\n      <a class=\"boton secundario\" href=\"${API}/orden.pdf\" target=\"_blank\">📄 Ver orden de servicio (PDF)</a></div>\n      <div class=\"tarjeta\"><h2>2. Firma de conformidad</h2>\n      <label style=\"font-size:13px; color:var(--gris);\">Tu nombre completo</label>\n      <input type=\"text\" id=\"nombre\" value=\"${esc(D.cliente_nombre)}\" autocomplete=\"name\" />\n      <p style=\"font-size:13px; color:var(--gris); margin:12px 0 6px;\">Firma aquí con tu dedo:</p>\n      <canvas id=\"firma\"></canvas>\n      <button class=\"boton secundario\" style=\"margin-top:8px; padding:9px; font-size:14px;\" onclick=\"limpiar()\">Borrar firma</button>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"acepto\" /> <span>Revisé la orden de servicio y estoy de acuerdo con los datos, el problema reportado y las condiciones.</span></label>\n      <button class=\"boton primario\" id=\"btnFirmar\" onclick=\"firmar()\">✍️ Firmar orden</button>\n      <div class=\"error\" id=\"err\"></div></div>`;\n  } else {\n    html += `<div class=\"tarjeta\"><p class=\"ok\" style=\"margin:0;\">✔ Orden firmada por ${esc(D.firma_nombre)} el ${fecha(D.firma_en)}.</p>\n      <a class=\"boton secundario\" style=\"margin-top:12px;\" href=\"${API}/orden.pdf\" target=\"_blank\">📄 Descargar orden firmada</a></div>`;\n    if (!D.resolucion) {\n      html += `<div class=\"tarjeta\"><h2>¿Qué sigue?</h2><p style=\"margin:0;\">Nuestro equipo de soporte está revisando tu equipo. Te avisaremos por WhatsApp en cuanto tengamos el diagnóstico.</p></div>`;\n    }\n  }\n  if (D.resolucion) {\n    const r = D.resolucion;\n    const refac = (r.refacciones || []).filter(x => x.descripcion);\n    html += `<div class=\"tarjeta\"><h2>Diagnóstico</h2><p>${esc(r.diagnostico).replace(/\\n/g, '<br>')}</p>\n      ${refac.length ? `<h2 style=\"margin-top:14px;\">Refacciones</h2><table><tr><th>Cant.</th><th>Descripción</th><th>No. de parte</th></tr>\n        ${refac.map(x => `<tr><td>${esc(x.cantidad)}</td><td>${esc(x.descripcion)}</td><td>${esc(x.numero_parte || '—')}</td></tr>`).join('')}</table>` : ''}\n      <h2 style=\"margin-top:14px;\">Qué se va a hacer</h2><p>${esc(r.resolucion).replace(/\\n/g, '<br>')}</p>\n      <h2 style=\"margin-top:14px;\">Envío</h2><dl><dt>Paquetería</dt><dd>${esc(r.paqueteria || 'Por confirmar')}</dd>\n      <dt>Ocurre</dt><dd>${r.ocurre === true ? 'Sí — lo recoges en la sucursal de la paquetería' : r.ocurre === false ? 'No — se entrega en tu domicilio' : 'Por confirmar'}</dd></dl>\n      <a class=\"boton secundario\" style=\"margin-top:14px;\" href=\"${API}/resolucion.pdf\" target=\"_blank\">📄 Descargar diagnóstico (PDF)</a></div>`;\n    if (D.encuesta_pendiente) {\n      html += `<div class=\"tarjeta\" id=\"encuesta\"><h2>⭐ Encuesta de satisfacción</h2>\n        <p style=\"margin-top:0;\">Nos ayuda mucho saber cómo te fue. Son 4 preguntas.</p>\n        <b>¿Qué tan satisfecho estás con tu equipo (producto)?</b><div class=\"estrellas\" data-k=\"satisfaccion_producto\"></div>\n        <b>¿Cómo calificas la atención de soporte?</b><div class=\"estrellas\" data-k=\"atencion\"></div>\n        <b>¿Qué tan rápido resolvimos?</b><div class=\"estrellas\" data-k=\"rapidez\"></div>\n        <b>Del 0 al 10, ¿nos recomendarías?</b><div class=\"nps\" data-k=\"recomendaria\"></div>\n        <b>Comentarios (opcional)</b><textarea id=\"comentarios\" rows=\"3\"></textarea>\n        <button class=\"boton primario\" style=\"margin-top:12px;\" onclick=\"enviarEncuesta(this)\">Enviar encuesta</button>\n        <div class=\"error\" id=\"errEnc\"></div></div>`;\n    } else if (D.encuesta_contestada) {\n      html += `<div class=\"tarjeta\"><p class=\"ok\" style=\"margin:0;\">⭐ ¡Gracias por contestar la encuesta!</p></div>`;\n    }\n  }\n  html += `<div class=\"pie\">${esc(D.empresa || '')} · Soporte técnico</div>`;\n  c.innerHTML = html;\n  if (!D.firmada) prepararFirma();\n  if (D.resolucion && D.encuesta_pendiente) prepararEncuesta();\n}\n\n// ---- Firma ----\nlet ctx = null, vacia = true, pintando = false;\nfunction prepararFirma() {\n  const cv = document.getElementById('firma');\n  const ajustar = () => {\n    const k = window.devicePixelRatio || 1;\n    cv.width = cv.clientWidth * k; cv.height = cv.clientHeight * k;\n    ctx = cv.getContext('2d'); ctx.scale(k, k); limpiar();\n  };\n  ajustar();\n  const pos = (e) => { const b = cv.getBoundingClientRect(); const t = e.touches ? e.touches[0] : e; return { x: t.clientX - b.left, y: t.clientY - b.top }; };\n  const ini = (e) => { e.preventDefault(); pintando = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); };\n  const mov = (e) => { if (!pintando) return; e.preventDefault(); vacia = false; const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); };\n  const fin = () => { pintando = false; };\n  cv.addEventListener('mousedown', ini); cv.addEventListener('mousemove', mov); window.addEventListener('mouseup', fin);\n  cv.addEventListener('touchstart', ini, { passive: false }); cv.addEventListener('touchmove', mov, { passive: false }); cv.addEventListener('touchend', fin);\n}\nfunction limpiar() {\n  const cv = document.getElementById('firma');\n  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, cv.width, cv.height); ctx.restore();\n  ctx.strokeStyle = '#111'; ctx.lineWidth = 2.6; ctx.lineCap = 'round'; ctx.lineJoin = 'round';\n  vacia = true;\n}\nasync function firmar() {\n  const err = document.getElementById('err'); err.textContent = '';\n  const nombre = document.getElementById('nombre').value.trim();\n  if (nombre.length < 3) { err.textContent = 'Escribe tu nombre completo.'; return; }\n  if (vacia) { err.textContent = 'Falta tu firma en el recuadro.'; return; }\n  if (!document.getElementById('acepto').checked) { err.textContent = 'Marca la casilla de conformidad.'; return; }\n  const btn = document.getElementById('btnFirmar'); btn.disabled = true; btn.textContent = 'Enviando…';\n  try {\n    const r = await fetch(`${API}/firmar`, { method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ nombre, firma_base64: document.getElementById('firma').toDataURL('image/png') }) });\n    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || 'No se pudo guardar la firma.');\n    await cargar();\n    window.scrollTo(0, 0);\n  } catch (e) { err.textContent = e.message; btn.disabled = false; btn.textContent = '✍️ Firmar orden'; }\n}\n\n// ---- Encuesta ----\nconst RESP = {};\nfunction prepararEncuesta() {\n  document.querySelectorAll('.estrellas').forEach(cont => {\n    const k = cont.dataset.k;\n    cont.innerHTML = [1, 2, 3, 4, 5].map(n => `<button type=\"button\" data-n=\"${n}\" aria-label=\"${n} de 5\">★</button>`).join('');\n    cont.querySelectorAll('button').forEach(b => b.onclick = () => {\n      RESP[k] = +b.dataset.n;\n      cont.querySelectorAll('button').forEach(x => x.classList.toggle('on', +x.dataset.n <= RESP[k]));\n    });\n  });\n  const nps = document.querySelector('.nps');\n  nps.innerHTML = Array.from({ length: 11 }, (_, n) => `<button type=\"button\" data-n=\"${n}\">${n}</button>`).join('');\n  nps.querySelectorAll('button').forEach(b => b.onclick = () => {\n    RESP.recomendaria = +b.dataset.n;\n    nps.querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b));\n  });\n}\nasync function enviarEncuesta(btn) {\n  const err = document.getElementById('errEnc'); err.textContent = '';\n  for (const k of ['satisfaccion_producto', 'atencion', 'rapidez', 'recomendaria']) {\n    if (RESP[k] === undefined) { err.textContent = 'Contesta las 4 preguntas, por favor.'; return; }\n  }\n  btn.disabled = true;\n  try {\n    const r = await fetch(`${API}/encuesta`, { method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ ...RESP, comentarios: document.getElementById('comentarios').value.trim() || null }) });\n    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || 'No se pudo enviar.');\n    await cargar();\n  } catch (e) { err.textContent = e.message; btn.disabled = false; }\n}\n\ncargar();\n</script>\n</body>\n</html>\n"
}

NUEVOS_BIN = {}


def main():
    if sys.version_info < (3, 0):
        print("Este script necesita Python 3. Correlo asi:  py -3 fix_soporte_tecnico_peymar.py")
        sys.exit(1)
    errores = []
    with open("backend/db.py", encoding="utf-8") as f:
        if "rh_sin_microsip" not in f.read():
            print("Primero corre fix_rh_sin_microsip_peymar.py (y los anteriores), y luego este.")
            sys.exit(1)
    cambios = {}
    for ruta, contenido in NUEVOS.items():
        if os.path.exists(ruta):
            with open(ruta, encoding="utf-8") as f:
                actual = f.read().replace("\r\n", "\n")
            if actual == contenido:
                continue
        cambios[ruta] = contenido
    bin_cambios = {}
    for ruta, b64 in NUEVOS_BIN.items():
        datos = base64.b64decode(b64)
        if os.path.exists(ruta):
            with open(ruta, "rb") as f:
                if f.read() == datos:
                    continue
        bin_cambios[ruta] = datos
    for ruta, pares in ARCHIVOS.items():
        if not os.path.exists(ruta):
            errores.append("No encontre {} -- corre el script desde la carpeta del repo.".format(ruta))
            continue
        with open(ruta, encoding="utf-8", newline="") as f:
            original = f.read()
        # Windows: el archivo puede tener saltos CRLF, LF o una mezcla.
        # Se trabaja todo en LF y al guardar se deja como estaba (CRLF si tenia).
        crlf = "\r\n" in original
        texto = original.replace("\r\n", "\n")
        inicial = texto
        for i, (viejo, nuevo) in enumerate(pares, 1):
            if nuevo in texto:
                continue  # ya aplicado
            n = texto.count(viejo)
            if n != 1:
                errores.append("{}: cambio #{} -- el texto a reemplazar aparece {} veces (se esperaba 1).".format(ruta, i, n))
                continue
            texto = texto.replace(viejo, nuevo, 1)
        if texto != inicial:
            cambios[ruta] = texto.replace("\n", "\r\n") if crlf else texto
    if errores:
        print("NO se aplico nada:")
        for e in errores:
            print("  -", e)
        sys.exit(1)
    for ruta, datos in bin_cambios.items():
        with open(ruta, "wb") as f:
            f.write(datos)
        print("Actualizado:", ruta)
    for ruta, texto in cambios.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("Actualizado:", ruta)
    if not cambios and not bin_cambios:
        print("Todo ya estaba aplicado, no hubo cambios.")
    else:
        print("Listo.")


if __name__ == "__main__":
    main()
